SELECT ?s ?p ?o WHERE {
  ?s rdf:type brick:ElectricPower .
  ?s brick:hasProperty ?p .
  FILTER(STR(?p) LIKE "%lighting%")
}

SELECT ?sensor ?zone WHERE {
  ?sensor rdf:type brick:ElectricPower .
  ?sensor brick:isAttachedTo ?zone .
  ?zone rdf:type brick:Zone .
  FILTER(?zone IN (ref:Core_bottom, ref:Perimeter_bot_ZN_4, ref:Perimeter_top_ZN_1))
}

SELECT ?s ?zone WHERE {
  ?s rdf:type brick:ElectricPower .
  ?s brick:isAttachedTo ?zone .
  FILTER(?zone IN (ref:Core_bottom, ref:Perimeter_bot_ZN_4, ref:Perimeter_top_ZN_1))
}

SELECT ?s WHERE {
  ?s rdf:type brick:ElectricPower .
  ?s brick:isAttachedTo ?zone .
  ?zone rdf:type brick:Zone .
}

SELECT ?name WHERE {
  ?s rdfs:label ?name .
  FILTER(?name IN (ref:Core_bottom, ref:Perimeter_bot_ZN_4, ref:Perimeter_top_ZN_1))
}

